def parse_query(qs: str) -> dict:
    def decode(s):
        s = s.replace('+', ' ')
        result = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '%':
                if i + 2 >= n or not all(ch in '0123456789abcdefABCDEF' for ch in s[i+1:i+3]):
                    raise ValueError('Malformed percent-escape')
                result.append(chr(int(s[i+1:i+3], 16)))
                i += 3
            else:
                result.append(c)
                i += 1
        return ''.join(result)

    result = {}
    for pair in qs.split('&'):
        if not pair:
            continue
        if '=' in pair:
            k, v = pair.split('=', 1)
        else:
            k, v = pair, ''
        k = decode(k)
        v = decode(v)
        result.setdefault(k, []).append(v)
    return result
